        let response = router
            .oneshot(request)
            .with_subscriber(buffer.subscriber(filter))
            .await
            .unwrap();
        let events = buffer.events();
        let output = serde_json::to_string(&events).unwrap();
        for secret in [
            "PRIVATE_AUTH_HEADER",
            "PRIVATE_REQUEST_BODY",
            "PRIVATE_QUERY",
        ] {
            assert!(!output.contains(secret), "leaked {secret}: {output}");
        }
        (response, events)
    }

